language "EAL/2";
environment test_run {
  require "service" == "orders-api";
  require "build_id" == "3ed2f0e927b396d61bcd4014be420def644ab9b39e3710f0e7a2d1e8312c9d3f";
  require "run_id" == "case-e73cfbd003da";
  require "dataset" == "measured_controlled_api";
}
tool api_load_test { version "2"; mode deterministic; }
evidence load_test {
  tool api_load_test; kind test; environment test_run; max_age 300;
  input {"build_id": "3ed2f0e927b396d61bcd4014be420def644ab9b39e3710f0e7a2d1e8312c9d3f", "concurrent_clients": 10, "report_id": "99341c0fdd67", "request_count": 100, "run_id": "case-e73cfbd003da", "service": "orders-api", "timeout_seconds": 3};
  require "report_valid" == true;
  require "identity_matches" == true;
  require "complete_records" == true;
  require "consistent_records" == true;
  require "request_count" >= 100;
  require "p95_ms" <= 200;
  require "error_rate_percent" <= 1;
}
reasoning acceptance_criteria {
  method "structured/1";
  rationale "The configured collector inspects an immutable report of real HTTP requests at the declared replay assessment time. Report validity, completeness, consistency, service, build, run and workload identity are required. The sample p95 uses nearest rank over every recorded attempt. Every non-2xx status or transport failure counts as an error. Passing these inclusive limits in fresh identified measurements supports only this run's stated performance criteria. The informal rationale is author supplied, not independently proved by structured/1.";
}
claim performance_criteria_met {
  statement "The measured orders-api run case-e73cfbd003da for build 3ed2f0e927b396d61bcd4014be420def644ab9b39e3710f0e7a2d1e8312c9d3f with 10 concurrent clients has at least 100 requests, nearest-rank sample p95 at most 200 ms and at most 1 percent failed requests, with matching response identities and observations no older than 300 seconds.";
  environment test_run;
}
argument checked_performance {
  conclusion performance_criteria_met; reasoning acceptance_criteria; evidence load_test;
}

